WITH WebEventsBySession AS (SELECT session_id, ROUND((100 * SUM(CASE WHEN page = '/home' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_home, MAX(event_time) AS latest_event_time FROM web_events GROUP BY session_id) SELECT s.id, s.browser, W.pct_home, W.latest_event_time FROM sessions s JOIN WebEventsBySession W ON s.id = W.session_id WHERE W.pct_home > 49 ORDER BY latest_event_time, id LIMIT 50
